default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Rpc' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('RestrictRemoteClients', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]1)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Rpc [RestrictRemoteClients]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if and (ne .Vars.win19cis_system_role "domaincontroller") .Vars.win19cis_level_2 }}
  {{ if .Vars.win19cis_rule_18_9_36_2 }}
    {{ if ne .Vars.win19cis_system_role "domaincontroller" }}
registry:
  HKLM\SOFTWARE\Policies\Microsoft\Windows NT\Rpc\RestrictRemoteClients:
    title: "18.9.36.2 | Ensure 'Restrict Unauthenticated RPC clients' is set to 'Enabled: Authenticated' (MS only) | RestrictRemoteClients"
    exists: true
    value: 1
    type: REG_DWORD
    meta:
      memberserver: 2
      server: 2
      CIS_ID:
        - 18.9.36.2
      NIST800-53R5:
        - SI-4
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Rpc')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Rpc' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Rpc' -Name 'RestrictRemoteClients' -Value 1 -PropertyType DWord -Force | Out-Null
exit 0
